package com.bookstore.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDateTime; import java.util.*;
@Entity @Table(name="orders")
public class Order { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="customer_id") private Customer customer; @Column(nullable=false) private LocalDateTime orderDate=LocalDateTime.now(); @Enumerated(EnumType.STRING) @Column(nullable=false) private OrderStatus status=OrderStatus.NEW; @Column(nullable=false,precision=12,scale=2) private BigDecimal total=BigDecimal.ZERO; @OneToMany(mappedBy="order",cascade=CascadeType.ALL,orphanRemoval=true) private List<OrderItem> items=new ArrayList<>(); public void addItem(OrderItem i){items.add(i);i.setOrder(this);} public Long getId(){return id;} public void setId(Long v){id=v;} public Customer getCustomer(){return customer;} public void setCustomer(Customer v){customer=v;} public LocalDateTime getOrderDate(){return orderDate;} public void setOrderDate(LocalDateTime v){orderDate=v;} public OrderStatus getStatus(){return status;} public void setStatus(OrderStatus v){status=v;} public BigDecimal getTotal(){return total;} public void setTotal(BigDecimal v){total=v;} public List<OrderItem> getItems(){return items;} public void setItems(List<OrderItem> v){items=v;} }
